define({"topics":[{"title":"Electrical Safety","shortdesc":"<p class=\"shortdesc\">You must follow all recommended safety procedures when servicing and working near energy sources.<\/p>","href":"r_ElectricalSafety_10.html","attributes":{"data-id":"id_2001693"},"menu":{"hasChildren":false},"tocID":"id_2001693-d46e106934","topics":[]},{"title":"<span class=\"ph\">Shutting down the host computer<\/span>","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_21.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e107036","topics":[]},{"title":"Applying LOTO - Integrated System Cabinet (ISC)","shortdesc":"<p class=\"shortdesc\">Apply LOTO to both the gradient and system Power Distribution Unit (PDU) breakers on the MDP when servicing either of these items in the ISC. Apply LOTO to make sure of a safe environment when working on these parts.<\/p>","href":"t_Applying-LOTO-ISC_20.html","attributes":{"data-id":"id_2001781"},"menu":{"hasChildren":false},"tocID":"id_2001781-d46e107139","topics":[]},{"title":"Removing the patient fan DCPS assembly","shortdesc":"<p class=\"shortdesc\"\/>","href":"t_RemovingThePatientFanDCPS.html","attributes":{"data-id":"id_2025023"},"menu":{"hasChildren":false},"tocID":"id_2025023-d46e107241","topics":[]},{"title":"Installing the patient fan DCPS assembly","shortdesc":"<p class=\"shortdesc\"\/>","href":"t_InstallingThePatientFanDCPS.html","attributes":{"data-id":"id_2025024"},"menu":{"hasChildren":false},"tocID":"id_2025024-d46e107342","topics":[]},{"title":"Removing LOTO - Integrated System Cabinet (ISC)","shortdesc":"<p class=\"shortdesc\">Remove LOTO from the gradient and system PDU breakers on the MDP before restoring power to the ISC.<\/p>","href":"t_Removing-LOTO-ISC_19.html","attributes":{"data-id":"id_2001783"},"menu":{"hasChildren":false},"tocID":"id_2001783-d46e107443","topics":[]},{"title":"Starting up the host computer","shortdesc":"<p class=\"shortdesc\">How to start the host computer.<\/p>","href":"t_StartingUpTheHostComputer_21.html","attributes":{"data-id":"id_2001468"},"menu":{"hasChildren":false},"tocID":"id_2001468-d46e107545","topics":[]},{"title":"Doing a TPS reset","shortdesc":"<p class=\"shortdesc\">This document provides instructions for doing a TPS reset and examples of the results output.<\/p>","href":"t_DoingTPSReset_Parent_12.html","attributes":{"data-id":"id_2001664"},"menu":{"hasChildren":false},"tocID":"id_2001664-d46e107647","topics":[]},{"title":"Doing a check scan","shortdesc":"<p class=\"shortdesc\"> A check scan is done at the beginning of some procedures and at the end of many procedures. This functional check assures the unit is in good clinical working order.<\/p>","href":"t_DoingACheckScan_Parent_20.html","attributes":{"data-id":"id_2001754"},"menu":{"hasChildren":false},"tocID":"id_2001754-d46e107749","topics":[]}]});